"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[746],{718:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-03-gradient-regularization</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-3-градиентный-спуск-обусловленность-и-регуляризация">Лабораторная\nработа 3. Градиентный спуск, обусловленность и регуляризация</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 2</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 2: градиентный спуск (опр. 2.1) и условие сходимости\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn><mo>&lt;</mo><mi>η</mi><mo>&lt;</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">0&lt;\\eta&lt;1/\\lambda_{\\max}</annotation></semantics></math>\n(утв. 2.2), SGD (опр. 2.4), мультиколлинеарность и неустойчивость\nрешения (утв. 2.5), гребневая регрессия (опр. 2.7, теорема 2.9), MAP\n(опр. 2.10, утв. 2.11), LASSO (опр. 2.12); лекция 1: нормальные\nуравнения, матричное дифференцирование</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–3) + 6 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Реализовать градиентный спуск и его стохастический вариант, проверить\nграницу шага\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">1/\\lambda_{\\max}</annotation></semantics></math>\nиз утверждения 2.2 и связь скорости сходимости с числом обусловленности;\nувидеть, как мультиколлинеарность разрушает решение МНК, и как обе\nрегуляризации это лечат; реализовать LASSO покоординатным спуском и\nобъяснить, откуда берётся разреженность.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab03_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<blockquote>\n<p><strong>О нормировке.</strong> В §1 лекции 2 функционал берётся без\nусреднения:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">Q(\\theta) = \\|X\\theta - y\\|^2</annotation></semantics></math>,\nпоэтому\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>∇</mi><mi>Q</mi><mo>=</mo><mn>2</mn><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\nabla Q = 2X^{\\mathsf T}(X\\theta - y)</annotation></semantics></math>\nи граница шага равна\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">1/\\lambda_{\\max}</annotation></semantics></math>.\nВ определении 2.4 (SGD) используется усреднённая форма\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><msub><mo>∑</mo><mi>i</mi></msub><msub><mi>Q</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">Q = \\frac1\\ell\\sum_i Q_i</annotation></semantics></math>.\nЭти два\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math>\nразличаются множителем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>,\nи потому «правильный» шаг для них отличается в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\nраз. <strong>Всегда проверяйте, какая нормировка у вашего\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>Q</mi><annotation encoding="application/x-tex">Q</annotation></semantics></math></strong>\n— это самая частая причина «почему у меня градиентный спуск разошёлся».\nНиже нормировка указана явно в каждой части.</p>\n</blockquote>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> optimize</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">3</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-градиентный-спуск-и-граница-шага">Часть 1. Градиентный\nспуск и граница шага</h1>\n<p>Определение 2.1:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo>+</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>=</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><msub><mi>η</mi><mi>t</mi></msub><mi>∇</mi><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta^{(t+1)} = \\theta^{(t)} - \\eta_t \\nabla Q(\\theta^{(t)})</annotation></semantics></math>.\nДля\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">Q(\\theta) = \\|X\\theta - y\\|^2</annotation></semantics></math>\nимеем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>∇</mi><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>2</mn><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\nabla Q(\\theta) = 2X^{\\mathsf T}(X\\theta - y)</annotation></semantics></math>.</p>\n<p>Утверждение 2.2 обещает сходимость при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn><mo>&lt;</mo><mi>η</mi><mo>&lt;</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">0 &lt; \\eta &lt; 1/\\lambda_{\\max}</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>λ</mi><mi>max</mi></msub><annotation encoding="application/x-tex">\\lambda_{\\max}</annotation></semantics></math>\n— наибольшее собственное число\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>.\nПроверим границу экспериментально: возьмём шаги\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi><mo>=</mo><mi>c</mi><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">\\eta = c/\\lambda_{\\max}</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi><mo>∈</mo><mo stretchy="false" form="prefix">{</mo><mn>0.1</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.5</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.9</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>1.0</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>1.05</mn><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">c \\in \\{0.1,\\ 0.5,\\ 0.9,\\ 1.0,\\ 1.05\\}</annotation></semantics></math>.</p>\n<p>Идея доказательства подсказывает, что именно смотреть: ошибка в\nсобственном базисе умножается на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mn>1</mn><mo>−</mo><mn>2</mn><mi>η</mi><msub><mi>λ</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">|1 - 2\\eta\\lambda_i|</annotation></semantics></math>,\nпоэтому при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi><mo>=</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">\\eta = 1/\\lambda_{\\max}</annotation></semantics></math>\nмножитель равен ровно\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>1</mn><annotation encoding="application/x-tex">1</annotation></semantics></math>\n(колебания без затухания), а при большем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>η</mi><annotation encoding="application/x-tex">\\eta</annotation></semantics></math>\n— превышает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>1</mn><annotation encoding="application/x-tex">1</annotation></semantics></math>\n(расходимость).</p>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> grad_Q(theta, X, y):</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Градиент Q(theta) = ||X theta - y||^2.&quot;&quot;&quot;</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> gradient_descent(X, y, eta, n_iter<span class="op">=</span><span class="dv">300</span>, theta0<span class="op">=</span><span class="va">None</span>):</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Возвращает траекторию (n_iter + 1, p) метода из определения 2.1.&quot;&quot;&quot;</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">200</span></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a>x1 <span class="op">=</span> rng.normal(<span class="dv">0</span>, <span class="dv">1</span>, n)</span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a>x2 <span class="op">=</span> <span class="fl">0.6</span> <span class="op">*</span> x1 <span class="op">+</span> <span class="fl">0.8</span> <span class="op">*</span> rng.normal(<span class="dv">0</span>, <span class="dv">1</span>, n)</span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a>X_gd <span class="op">=</span> np.column_stack([x1, x2])</span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a>theta_true <span class="op">=</span> np.array([<span class="fl">2.0</span>, <span class="op">-</span><span class="fl">1.0</span>])</span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a>y_gd <span class="op">=</span> X_gd <span class="op">@</span> theta_true <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.5</span>, n)</span>\n<span id="cb3-17"><a href="#cb3-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-18"><a href="#cb3-18" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) найдите theta* через lstsq и lambda_max = max собственное число X^T X;</span></span>\n<span id="cb3-19"><a href="#cb3-19" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) для c in [0.1, 0.5, 0.9, 1.0, 1.05] запустите ГС с шагом c / lambda_max;</span></span>\n<span id="cb3-20"><a href="#cb3-20" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) на одном графике (полулогарифмическом по оси Q) покажите</span></span>\n<span id="cb3-21"><a href="#cb3-21" aria-hidden="true" tabindex="-1"></a><span class="co">#          Q(theta^(t)) - Q(theta*) для каждого шага.</span></span>\n<span id="cb3-22"><a href="#cb3-22" aria-hidden="true" tabindex="-1"></a><span class="co">#       Осторожно: при расходимости значения станут inf -- замаскируйте их np.nan.</span></span></code></pre></div>\n</div>\n<div id="cell007" class="cell markdown">\n<h3 id="задание-12-траектории-на-линиях-уровня">Задание 1.2. Траектории\nна линиях уровня</h3>\n<p>Постройте линии уровня\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(\\theta)</annotation></semantics></math>\nна плоскости\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>,</mo><msub><mi>θ</mi><mn>2</mn></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(\\theta_1, \\theta_2)</annotation></semantics></math>\nи нанесите траектории спуска для двух шагов: маленького и близкого к\nгранице. Отметьте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>θ</mi><mo>*</mo></msup><annotation encoding="application/x-tex">\\theta^*</annotation></semantics></math>.</p>\n</div>\n<div id="cell008" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: линии уровня Q(theta) на сетке вокруг theta* и две траектории спуска</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       (маленький шаг и шаг у границы). Отметьте theta*.</span></span></code></pre></div>\n</div>\n<div id="cell009" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> При каком\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>c</mi><annotation encoding="application/x-tex">c</annotation></semantics></math>\nспуск перестал сходиться? Совпало ли это с границей утверждения 2.2? Как\nвыглядит траектория при шаге, близком к границе, и почему она такая?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell010" class="cell markdown">\n<hr />\n<h1 id="часть-2-скорость-сходимости-и-число-обусловленности">Часть 2.\nСкорость сходимости и число обусловленности</h1>\n<p>Из того же разложения по собственным векторам следует: при\nоптимальном постоянном шаге\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi><mo>=</mo><mn>1</mn><mi>/</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>λ</mi><mi>max</mi></msub><mo>+</mo><msub><mi>λ</mi><mi>min</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\eta = 1/(\\lambda_{\\max} + \\lambda_{\\min})</annotation></semantics></math>\nошибка убывает как</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><msup><mi>θ</mi><mo>*</mo></msup><mo stretchy="false" form="postfix">∥</mo><mspace width="0.278em"></mspace><mo>≤</mo><mspace width="0.278em"></mspace><mo minsize="180%" maxsize="180%" stretchy="true" form="prefix">(</mo><mfrac><mrow><mi>κ</mi><mo>−</mo><mn>1</mn></mrow><mrow><mi>κ</mi><mo>+</mo><mn>1</mn></mrow></mfrac><msup><mo minsize="180%" maxsize="180%" stretchy="true" form="postfix">)</mo><mi>t</mi></msup><mspace width="0.167em"></mspace><mo stretchy="false" form="postfix">∥</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><msup><mi>θ</mi><mo>*</mo></msup><mo stretchy="false" form="postfix">∥</mo><mo>,</mo><mspace width="2.0em"></mspace><mi>κ</mi><mo>=</mo><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><msub><mi>λ</mi><mi>max</mi></msub><msub><mi>λ</mi><mi>min</mi></msub></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\|\\theta^{(t)} - \\theta^*\\| \\;\\le\\; \\Bigl(\\frac{\\kappa - 1}{\\kappa + 1}\\Bigr)^{t}\n\\,\\|\\theta^{(0)} - \\theta^*\\|,\n\\qquad \\kappa = \\mathrm{cond}(X^{\\mathsf T}X) = \\frac{\\lambda_{\\max}}{\\lambda_{\\min}} .\n</annotation></semantics></math></p>\n<p>Значит, число итераций до заданной точности растёт <strong>линейно по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>κ</mi><annotation encoding="application/x-tex">\\kappa</annotation></semantics></math></strong>.\nПроверьте это: постройте матрицы с заданным\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>κ</mi><annotation encoding="application/x-tex">\\kappa</annotation></semantics></math>\nи измерьте число итераций до\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><msup><mi>θ</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>t</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><msup><mi>θ</mi><mo>*</mo></msup><mo stretchy="false" form="postfix">∥</mo><mo>&lt;</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>6</mn></mrow></msup><mo stretchy="false" form="postfix">∥</mo><msup><mi>θ</mi><mo>*</mo></msup><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta^{(t)} - \\theta^*\\| &lt; 10^{-6}\\|\\theta^*\\|</annotation></semantics></math>.</p>\n</div>\n<div id="cell011" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> design_with_cond(n, p, kappa, generator):</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Матрица X, у которой cond(X^T X) = kappa.&quot;&quot;&quot;</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: возьмите случайную матрицу, разложите её по SVD и подмените</span></span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">#       сингулярные числа на np.logspace(0, -0.5*log10(kappa), p)</span></span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> iters_to_converge(X, y, tol<span class="op">=</span><span class="fl">1e-6</span>, max_iter<span class="op">=</span><span class="dv">400_000</span>):</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Число итераций ГС с шагом 1/(lambda_max + lambda_min) до заданной точности.&quot;&quot;&quot;</span></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для kappa из np.logspace(1, 4.5, 8) постройте задачу, измерьте число итераций,</span></span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a><span class="co">#       выведите таблицу и график в двойном логарифмическом масштабе вместе с</span></span>\n<span id="cb5-15"><a href="#cb5-15" aria-hidden="true" tabindex="-1"></a><span class="co">#       эталонной прямой, пропорциональной kappa.</span></span></code></pre></div>\n</div>\n<div id="cell012" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Как число итераций зависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>κ</mi><annotation encoding="application/x-tex">\\kappa</annotation></semantics></math>?\nВо сколько раз медленнее сходится задача с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>κ</mi><mo>=</mo><msup><mn>10</mn><mn>5</mn></msup></mrow><annotation encoding="application/x-tex">\\kappa = 10^5</annotation></semantics></math>\nпо сравнению с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>κ</mi><mo>=</mo><mn>10</mn></mrow><annotation encoding="application/x-tex">\\kappa = 10</annotation></semantics></math>?\nЧто это означает практически для признаков, измеренных в разных\nединицах?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell013" class="cell markdown">\n<hr />\n<h1 id="часть-3-стохастический-градиентный-спуск">Часть 3.\nСтохастический градиентный спуск</h1>\n<p>Определение 2.4 использует <strong>усреднённый</strong> функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><msubsup><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>ℓ</mi></msubsup><msub><mi>Q</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(\\theta) = \\frac1\\ell\\sum_{i=1}^{\\ell} Q_i(\\theta)</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>Q</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mo stretchy="false" form="prefix">⟨</mo><mi>θ</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">⟩</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">Q_i(\\theta) = (\\langle\\theta, x_i\\rangle - y_i)^2</annotation></semantics></math>.\nТогда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>∇</mi><msub><mi>Q</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>2</mn><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><mo stretchy="false" form="prefix">⟨</mo><mi>θ</mi><mo>,</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">⟩</mo><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\nabla Q_i(\\theta) = 2x_i(\\langle\\theta,x_i\\rangle - y_i)</annotation></semantics></math>,\nа для мини-пакета\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>B</mi><annotation encoding="application/x-tex">B</annotation></semantics></math>\nградиент усредняется по объектам пакета.</p>\n<p>Ключевой факт из лекции: при <strong>постоянном</strong> шаге SGD не\nсходится, а колеблется в окрестности\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>θ</mi><mo>*</mo></msup><annotation encoding="application/x-tex">\\theta^*</annotation></semantics></math>;\nдля сходимости нужен убывающий шаг, удовлетворяющий условию\nРоббинса–Монро\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∑</mo><msub><mi>η</mi><mi>t</mi></msub><mo>=</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\sum\\eta_t = \\infty</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>∑</mo><msubsup><mi>η</mi><mi>t</mi><mn>2</mn></msubsup><mo>&lt;</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\sum\\eta_t^2 &lt; \\infty</annotation></semantics></math>.</p>\n<p>Ваш вариант задаёт размеры пакетов\n<code>variant[&quot;batch_sizes&quot;]</code> и правило шага\n<code>variant[&quot;gd_flavor&quot;]</code>.</p>\n</div>\n<div id="cell014" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> sgd(X, y, eta0, n_epochs<span class="op">=</span><span class="dv">40</span>, batch_size<span class="op">=</span><span class="dv">1</span>, schedule<span class="op">=</span><span class="st">&quot;const&quot;</span>, generator<span class="op">=</span><span class="va">None</span>):</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;SGD/mini-batch для УСРЕДНЁННОГО Q. Возвращает (theta, история Q по эпохам).</span></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="co">    schedule: &#39;const&#39; -- eta_t = eta0; &#39;sqrt&#39; -- eta0/sqrt(t); &#39;inverse&#39; -- eta0/t,</span></span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="co">    где t -- номер шага (не эпохи).</span></span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) на одном графике сравните сходимость при разных batch_size</span></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a><span class="co">#          из variant[&quot;batch_sizes&quot;] и при полном градиенте (постоянный шаг);</span></span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) на втором графике сравните три расписания шага при batch_size=1.</span></span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a><span class="co">#       По оси Q откладывайте Q - Q*, масштаб логарифмический.</span></span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;правило шага по вашему варианту:&quot;</span>, variant[<span class="st">&quot;gd_flavor&quot;</span>])</span></code></pre></div>\n</div>\n<div id="cell015" class="cell markdown">\n<h3 id="задание-32-правило-шага-из-вашего-варианта">Задание 3.2. Правило\nшага из вашего варианта</h3>\n<p>Реализуйте правило шага, указанное в\n<code>variant[&quot;gd_flavor&quot;]</code>:</p>\n<ul>\n<li><strong>постоянный шаг</strong> — сравните три значения\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>η</mi><mn>0</mn></msub><annotation encoding="application/x-tex">\\eta_0</annotation></semantics></math>\nи покажите зависимость высоты «полки» от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>η</mi><mn>0</mn></msub><annotation encoding="application/x-tex">\\eta_0</annotation></semantics></math>;</li>\n<li><strong>затухающий шаг\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>η</mi><mi>t</mi></msub><mo>=</mo><msub><mi>η</mi><mn>0</mn></msub><mi>/</mi><msqrt><mi>t</mi></msqrt></mrow><annotation encoding="application/x-tex">\\eta_t = \\eta_0/\\sqrt t</annotation></semantics></math></strong>\n— проверьте условие Роббинса–Монро для этого расписания (какой из двух\nрядов сходится, какой расходится?);</li>\n<li><strong>шаг по Армихо</strong> — реализуйте дробление шага: пока\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo>−</mo><mi>η</mi><mi>∇</mi><mi>Q</mi><mo stretchy="false" form="postfix">)</mo><mo>&gt;</mo><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>c</mi><mspace width="0.167em"></mspace><mi>η</mi><mo stretchy="false" form="postfix">∥</mo><mi>∇</mi><mi>Q</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">Q(\\theta - \\eta\\nabla Q) &gt; Q(\\theta) - c\\,\\eta\\|\\nabla Q\\|^2</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>c</mi><mo>=</mo><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup></mrow><annotation encoding="application/x-tex">c = 10^{-4}</annotation></semantics></math>,\nумножайте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>η</mi><annotation encoding="application/x-tex">\\eta</annotation></semantics></math>\nна\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>0.5</mn><annotation encoding="application/x-tex">0.5</annotation></semantics></math>;\nсравните число итераций с постоянным шагом.</li>\n</ul>\n</div>\n<div id="cell016" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>flavor <span class="op">=</span> variant[<span class="st">&quot;gd_flavor&quot;</span>]</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;вариант:&quot;</span>, flavor)</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: реализуйте задание для СВОЕГО правила шага (см. текст выше).</span></span></code></pre></div>\n</div>\n<div id="cell017" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему при постоянном шаге SGD не сходится в\nточку, а мини-пакет размера\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>\n— сходится? Как высота «полки» зависит от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>η</mi><mn>0</mn></msub><annotation encoding="application/x-tex">\\eta_0</annotation></semantics></math>\nи от размера пакета?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell018" class="cell markdown">\n<hr />\n<h1 id="часть-4-мультиколлинеарность">Часть 4. Мультиколлинеарность</h1>\n<p>Начнём с примера из лекции 2:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℓ</mi><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">\\ell = 3</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mn>1</mn></msub><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>,</mo><mn>2</mn><mo>,</mo><mn>3</mn><msup><mo stretchy="false" form="postfix">)</mo><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">f_1 = (1,2,3)^{\\mathsf T}</annotation></semantics></math>,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>f</mi><mn>2</mn></msub><mo>=</mo><mn>2</mn><msub><mi>f</mi><mn>1</mn></msub></mrow><annotation encoding="application/x-tex">f_2 = 2f_1</annotation></semantics></math>.\nТогда</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mrow><mo stretchy="true" form="prefix">(</mo><mtable><mtr><mtd columnalign="center" style="text-align: center"><mn>1</mn></mtd><mtd columnalign="center" style="text-align: center"><mn>2</mn></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><mn>2</mn></mtd><mtd columnalign="center" style="text-align: center"><mn>4</mn></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><mn>3</mn></mtd><mtd columnalign="center" style="text-align: center"><mn>6</mn></mtd></mtr></mtable><mo stretchy="true" form="postfix">)</mo></mrow><mo>,</mo><mspace width="2.0em"></mspace><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>=</mo><mrow><mo stretchy="true" form="prefix">(</mo><mtable><mtr><mtd columnalign="center" style="text-align: center"><mn>14</mn></mtd><mtd columnalign="center" style="text-align: center"><mn>28</mn></mtd></mtr><mtr><mtd columnalign="center" style="text-align: center"><mn>28</mn></mtd><mtd columnalign="center" style="text-align: center"><mn>56</mn></mtd></mtr></mtable><mo stretchy="true" form="postfix">)</mo></mrow><mo>,</mo><mspace width="2.0em"></mspace><mrow><mi>det</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>0</mn><mi>.</mi></mrow><annotation encoding="application/x-tex">\nX = \\begin{pmatrix}1&amp;2\\\\2&amp;4\\\\3&amp;6\\end{pmatrix},\\qquad\nX^{\\mathsf T}X = \\begin{pmatrix}14&amp;28\\\\28&amp;56\\end{pmatrix},\\qquad\n\\det(X^{\\mathsf T}X) = 0 .\n</annotation></semantics></math></p>\n<p>Затем перейдём к более реалистичному случаю «почти коллинеарных»\nпризнаков с корреляцией\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ρ</mi><annotation encoding="application/x-tex">\\rho</annotation></semantics></math>\nиз вашего варианта и проверим утверждение 2.5:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mo stretchy="false" form="postfix">∥</mo><mi>δ</mi><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow><mrow><mo stretchy="false" form="postfix">∥</mo><mi>θ</mi><mo stretchy="false" form="postfix">∥</mo></mrow></mfrac><mspace width="0.278em"></mspace><mo>≤</mo><mspace width="0.278em"></mspace><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><mfrac><mrow><mo stretchy="false" form="postfix">∥</mo><mi>δ</mi><mi>b</mi><mo stretchy="false" form="postfix">∥</mo></mrow><mrow><mo stretchy="false" form="postfix">∥</mo><mi>b</mi><mo stretchy="false" form="postfix">∥</mo></mrow></mfrac><mo>,</mo><mspace width="2.0em"></mspace><mi>A</mi><mo>=</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>,</mo><mspace width="0.278em"></mspace><mi>b</mi><mo>=</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\frac{\\|\\delta\\theta\\|}{\\|\\theta\\|} \\;\\le\\; \\mathrm{cond}(A)\\,\n\\frac{\\|\\delta b\\|}{\\|b\\|},\\qquad A = X^{\\mathsf T}X,\\; b = X^{\\mathsf T}y .\n</annotation></semantics></math></p>\n</div>\n<div id="cell019" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (1) воспроизведите вырожденный пример лекции: X = [[1,2],[2,4],[3,6]],</span></span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a><span class="co">#           выведите X^T X, её определитель и ранг, попробуйте np.linalg.solve.</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (2) постройте почти коллинеарные признаки с rho = variant[&quot;collinearity&quot;],</span></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a><span class="co">#           решите МНК и выведите cond(X^T X).</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (3) проверьте неравенство утверждения 2.5: 200 раз возмутите b так, чтобы</span></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a><span class="co">#           ||db||/||b|| = 1e-3, и сравните наблюдаемое ||dtheta||/||theta||</span></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a><span class="co">#           с оценкой cond(A) * 1e-3.</span></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (4) 300 бутстреп-выборок: нарисуйте облако оценок (theta_1, theta_2),</span></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a><span class="co">#           выведите их стандартное отклонение и корреляцию.</span></span></code></pre></div>\n</div>\n<div id="cell020" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Вдоль какого направления вытянуто облако\nбутстреп-оценок и почему? Насколько оценка утверждения 2.5 консервативна\n(во сколько раз медианное возмущение меньше границы)?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell021" class="cell markdown">\n<hr />\n<h1 id="часть-5-гребневая-регрессия">Часть 5. Гребневая регрессия</h1>\n<p>Определение 2.7 и теорема 2.9:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>Q</mi><mi>λ</mi></msub><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>λ</mi><mspace width="0.167em"></mspace><msup><mi>θ</mi><mi>𝖳</mi></msup><mi>D</mi><mi>θ</mi><mo>,</mo><mspace width="2.0em"></mspace><msubsup><mi>θ</mi><mi>λ</mi><mo>*</mo></msubsup><mo>=</mo><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>+</mo><mi>λ</mi><mi>D</mi><msup><mo stretchy="false" form="postfix">)</mo><mrow><mi>−</mi><mn>1</mn></mrow></msup><msup><mi>X</mi><mi>𝖳</mi></msup><mi>y</mi><mo>,</mo><mspace width="2.0em"></mspace><mi>D</mi><mo>=</mo><mrow><mi mathvariant="normal">d</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">g</mi></mrow><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo>,</mo><mi>…</mi><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nQ_\\lambda(\\theta) = \\|X\\theta - y\\|^2 + \\lambda\\,\\theta^{\\mathsf T}D\\theta,\n\\qquad\n\\theta^*_\\lambda = (X^{\\mathsf T}X + \\lambda D)^{-1}X^{\\mathsf T}y,\n\\qquad\nD = \\mathrm{diag}(0, 1, \\dots, 1).\n</annotation></semantics></math></p>\n<p>Матрица\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi><mo>+</mo><mi>λ</mi><mi>D</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X + \\lambda D</annotation></semantics></math>\nположительно определена при любом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\lambda &gt; 0</annotation></semantics></math>\n— <strong>даже если\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nвырождена</strong>. Проверим это на том самом примере, где\n<code>np.linalg.solve</code> только что отказал.</p>\n</div>\n<div id="cell022" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> ridge_fit(X, y, lam):</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;theta*_lambda по теореме 2.9. Первый столбец X считается столбцом единиц.&quot;&quot;&quot;</span></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span><span class="co">: соберите D = diag(0, 1, ..., 1) и решите (X^T X + lambda D) theta = X^T y</span></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: (1) примените ridge_fit к вырожденной задаче из части 4 при</span></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a><span class="co">#           lambda = 0, 1e-8, 1e-3, 1 -- посмотрите, при каком lambda решение появляется</span></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a><span class="co">#           и как меняется ||theta||;</span></span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       (2) постройте регуляризационный путь theta_j(lambda) на почти коллинеарных</span></span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a><span class="co">#           данных для lambdas = eval(variant[&quot;lambda_grid&quot;]).</span></span></code></pre></div>\n</div>\n<div id="cell023" class="cell markdown">\n<h3 id="задание-52-гребневая-регрессия-глазами-svd">Задание 5.2.\nГребневая регрессия глазами SVD</h3>\n<p>Пусть данные центрированы (тогда свободный член отделяется и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>D</mi><mo>=</mo><mi>I</mi></mrow><annotation encoding="application/x-tex">D = I</annotation></semantics></math>),\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mi>U</mi><mi mathvariant="normal">Σ</mi><msup><mi>V</mi><mi>𝖳</mi></msup></mrow><annotation encoding="application/x-tex">X = U\\Sigma V^{\\mathsf T}</annotation></semantics></math>.\nТогда</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>θ</mi><mi>λ</mi><mo>*</mo></msubsup><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><munder><mo>∑</mo><mi>i</mi></munder><mfrac><msub><mi>σ</mi><mi>i</mi></msub><mrow><msubsup><mi>σ</mi><mi>i</mi><mn>2</mn></msubsup><mo>+</mo><mi>λ</mi></mrow></mfrac><mspace width="0.167em"></mspace><mo stretchy="false" form="prefix">(</mo><msubsup><mi>u</mi><mi>i</mi><mi>𝖳</mi></msubsup><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><msub><mi>v</mi><mi>i</mi></msub><mo>,</mo><mspace width="2.0em"></mspace><mrow><mtext mathvariant="normal">при </mtext><mspace width="0.333em"></mspace></mrow><mi>λ</mi><mo>=</mo><mn>0</mn><mo>:</mo><mspace width="1.0em"></mspace><msup><mi>θ</mi><mo>*</mo></msup><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><mfrac><mn>1</mn><msub><mi>σ</mi><mi>i</mi></msub></mfrac><mo stretchy="false" form="prefix">(</mo><msubsup><mi>u</mi><mi>i</mi><mi>𝖳</mi></msubsup><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><msub><mi>v</mi><mi>i</mi></msub><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\theta^*_\\lambda \\;=\\; \\sum_{i} \\frac{\\sigma_i}{\\sigma_i^2 + \\lambda}\\,\n(u_i^{\\mathsf T} y)\\, v_i ,\n\\qquad\\text{при }\\lambda = 0:\\quad\n\\theta^* = \\sum_i \\frac{1}{\\sigma_i}(u_i^{\\mathsf T}y)\\, v_i .\n</annotation></semantics></math></p>\n<p>То есть ridge <strong>сжимает</strong> вклад\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>i</mi><annotation encoding="application/x-tex">i</annotation></semantics></math>-й\nкомпоненты в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>σ</mi><mi>i</mi><mn>2</mn></msubsup><mi>/</mi><mo stretchy="false" form="prefix">(</mo><msubsup><mi>σ</mi><mi>i</mi><mn>2</mn></msubsup><mo>+</mo><mi>λ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\sigma_i^2/(\\sigma_i^2+\\lambda)</annotation></semantics></math>\nраз, и сильнее всего — там, где\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>σ</mi><mi>i</mi></msub><annotation encoding="application/x-tex">\\sigma_i</annotation></semantics></math>\nмало, то есть по «плохо определённым» направлениям. Проверьте формулу\nчисленно и постройте графики коэффициентов сжатия.</p>\n</div>\n<div id="cell024" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) центрируйте X_col и y_col, разложите X по SVD;</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) проверьте формулу theta = V diag(s/(s^2+lam)) U^T y для нескольких lambda,</span></span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="co">#          сравнив с прямым решением (X^T X + lam I) theta = X^T y;</span></span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) постройте графики коэффициентов сжатия s_i^2/(s_i^2 + lambda).</span></span></code></pre></div>\n</div>\n<div id="cell025" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> По каким направлениям ridge сжимает решение\nсильнее и почему это разумно? Что происходит с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><msubsup><mi>θ</mi><mi>λ</mi><mo>*</mo></msubsup><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\theta^*_\\lambda\\|</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\lambda \\to \\infty</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell026" class="cell markdown">\n<hr />\n<h1 id="часть-6-lasso-и-покоординатный-спуск">Часть 6. LASSO и\nпокоординатный спуск</h1>\n<p>Определение 2.12:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msubsup><mi>θ</mi><mi>λ</mi><mo>*</mo></msubsup><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><msub><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>θ</mi></msub><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>λ</mi><msub><mo>∑</mo><mrow><mi>j</mi><mo>≥</mo><mn>1</mn></mrow></msub><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta^*_\\lambda = \\arg\\min_\\theta\\bigl(\\|X\\theta - y\\|^2 + \\lambda\\sum_{j\\ge1}|\\theta_j|\\bigr)</annotation></semantics></math>.\nЯвной формулы нет, но при фиксированных остальных координатах задача по\nодной координате решается точно. Обозначим\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>r</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mi>j</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>=</mo><mi>y</mi><mo>−</mo><msub><mo>∑</mo><mrow><mi>k</mi><mo>≠</mo><mi>j</mi></mrow></msub><msub><mi>x</mi><mi>k</mi></msub><msub><mi>θ</mi><mi>k</mi></msub></mrow><annotation encoding="application/x-tex">r^{(-j)} = y - \\sum_{k\\ne j} x_k\\theta_k</annotation></semantics></math>;\nтогда минимизируется\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><msup><mi>r</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mi>j</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo>−</mo><msub><mi>x</mi><mi>j</mi></msub><msub><mi>θ</mi><mi>j</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><mi>λ</mi><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">\\|r^{(-j)} - x_j\\theta_j\\|^2 + \\lambda|\\theta_j|</annotation></semantics></math>,\nи из условия на субградиент</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>θ</mi><mi>j</mi></msub><mspace width="0.278em"></mspace><mo>=</mo><mspace width="0.278em"></mspace><mfrac><mrow><mi>S</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mo stretchy="false" form="prefix">⟨</mo><msub><mi>x</mi><mi>j</mi></msub><mo>,</mo><msup><mi>r</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>−</mi><mi>j</mi><mo stretchy="false" form="postfix">)</mo></mrow></msup><mo stretchy="false" form="postfix">⟩</mo><mo>,</mo><mspace width="0.278em"></mspace><mi>λ</mi><mi>/</mi><mn>2</mn><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><mrow><mo stretchy="false" form="postfix">∥</mo><msub><mi>x</mi><mi>j</mi></msub><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow></mfrac><mo>,</mo><mspace width="2.0em"></mspace><mi>S</mi><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo>,</mo><mi>γ</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mrow><mi mathvariant="normal">s</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">g</mi><mi mathvariant="normal">n</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>z</mi><mo stretchy="false" form="postfix">)</mo><mspace width="0.167em"></mspace><mrow><mi>max</mi><mo>⁡</mo></mrow><mo stretchy="false" form="prefix">(</mo><mo stretchy="false" form="prefix">|</mo><mi>z</mi><mo stretchy="false" form="prefix">|</mo><mi>−</mi><mi>γ</mi><mo>,</mo><mspace width="0.167em"></mspace><mn>0</mn><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\theta_j \\;=\\; \\frac{S\\bigl(\\langle x_j, r^{(-j)}\\rangle,\\; \\lambda/2\\bigr)}{\\|x_j\\|^2},\n\\qquad\nS(z, \\gamma) = \\mathrm{sign}(z)\\,\\max(|z| - \\gamma,\\, 0).\n</annotation></semantics></math></p>\n<p>Функция\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>S</mi><annotation encoding="application/x-tex">S</annotation></semantics></math>\n— «мягкий порог»: она <strong>обнуляет</strong> координату, если её\nвклад меньше порога. Отсюда и разреженность.</p>\n</div>\n<div id="cell027" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> soft_threshold(z, gamma):</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;S(z, gamma) = sign(z) * max(|z| - gamma, 0).&quot;&quot;&quot;</span></span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> lasso_cd(X, y, lam, n_iter<span class="op">=</span><span class="dv">300</span>, tol<span class="op">=</span><span class="fl">1e-10</span>):</span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Покоординатный спуск. Первый столбец X -- единицы, он не штрафуется.&quot;&quot;&quot;</span></span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-10"><a href="#cb11-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-11"><a href="#cb11-11" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> Lasso</span>\n<span id="cb11-12"><a href="#cb11-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-13"><a href="#cb11-13" aria-hidden="true" tabindex="-1"></a>n_obj <span class="op">=</span> <span class="dv">120</span></span>\n<span id="cb11-14"><a href="#cb11-14" aria-hidden="true" tabindex="-1"></a>X_sp <span class="op">=</span> rng.normal(size<span class="op">=</span>(n_obj, <span class="dv">12</span>))</span>\n<span id="cb11-15"><a href="#cb11-15" aria-hidden="true" tabindex="-1"></a>theta_sparse <span class="op">=</span> np.zeros(<span class="dv">12</span>)<span class="op">;</span> theta_sparse[[<span class="dv">0</span>, <span class="dv">3</span>, <span class="dv">7</span>]] <span class="op">=</span> [<span class="fl">3.0</span>, <span class="op">-</span><span class="fl">2.0</span>, <span class="fl">1.5</span>]</span>\n<span id="cb11-16"><a href="#cb11-16" aria-hidden="true" tabindex="-1"></a>y_sp <span class="op">=</span> X_sp <span class="op">@</span> theta_sparse <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.3</span>, n_obj)</span>\n<span id="cb11-17"><a href="#cb11-17" aria-hidden="true" tabindex="-1"></a>X_sp1 <span class="op">=</span> np.column_stack([np.ones(n_obj), X_sp])</span>\n<span id="cb11-18"><a href="#cb11-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-19"><a href="#cb11-19" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сверьте свою реализацию со sklearn.linear_model.Lasso для нескольких lambda.</span></span>\n<span id="cb11-20"><a href="#cb11-20" aria-hidden="true" tabindex="-1"></a><span class="co">#       Внимание на нормировку: функционал sklearn -- (1/2n)||y - Xw||^2 + alpha||w||_1,</span></span>\n<span id="cb11-21"><a href="#cb11-21" aria-hidden="true" tabindex="-1"></a><span class="co">#       наш -- ||X theta - y||^2 + lambda ||theta||_1. Выразите alpha через lambda.</span></span></code></pre></div>\n</div>\n<div id="cell028" class="cell markdown">\n<h3 id="задание-62-ridge-против-lasso-пути-и-разреженность">Задание 6.2.\nRidge против LASSO: пути и разреженность</h3>\n<p>Постройте на одном рисунке регуляризационные пути обоих методов для\nразреженной задачи (истинные ненулевые координаты — три из двенадцати) и\nграфик числа ненулевых координат в зависимости от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>.</p>\n</div>\n<div id="cell029" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a>lambdas <span class="op">=</span> np.logspace(<span class="op">-</span><span class="dv">2</span>, <span class="fl">3.5</span>, <span class="dv">60</span>)</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте пути обоих методов и график числа ненулевых координат от lambda.</span></span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a><span class="co">#       Выделите цветом те координаты, истинное значение которых не равно нулю</span></span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       (индексы 0, 3, 7 в theta_sparse).</span></span></code></pre></div>\n</div>\n<div id="cell030" class="cell markdown">\n<h3 id="задание-63-почему-l_1-обнуляет-а-l_2--нет">Задание 6.3. Почему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>1</mn></msub><annotation encoding="application/x-tex">L_1</annotation></semantics></math>\nобнуляет, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>L</mi><mn>2</mn></msub><annotation encoding="application/x-tex">L_2</annotation></semantics></math>\n— нет</h3>\n<p>Воспроизведите геометрическую картинку из лекции 2: линии уровня\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(\\theta)</annotation></semantics></math>\nи множества\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">{</mo><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mn>1</mn></msub><mo stretchy="false" form="prefix">|</mo><mi>+</mi><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mn>2</mn></msub><mo stretchy="false" form="prefix">|</mo><mo>≤</mo><mi>c</mi><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\{|\\theta_1| + |\\theta_2| \\le c\\}</annotation></semantics></math>\n(ромб) и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">{</mo><msubsup><mi>θ</mi><mn>1</mn><mn>2</mn></msubsup><mo>+</mo><msubsup><mi>θ</mi><mn>2</mn><mn>2</mn></msubsup><mo>≤</mo><msup><mi>c</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">}</mo></mrow><annotation encoding="application/x-tex">\\{\\theta_1^2 + \\theta_2^2 \\le c^2\\}</annotation></semantics></math>\n(круг). Точка касания линии уровня с ромбом попадает в вершину — а\nвершины ромба лежат на осях.</p>\n</div>\n<div id="cell031" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a>Xg <span class="op">=</span> np.array([[<span class="fl">1.0</span>, <span class="fl">0.35</span>], [<span class="fl">0.35</span>, <span class="fl">1.0</span>], [<span class="fl">0.5</span>, <span class="fl">0.7</span>]])</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a>yg <span class="op">=</span> np.array([<span class="fl">1.4</span>, <span class="fl">0.6</span>, <span class="fl">1.0</span>])</span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте два рисунка: линии уровня Q и ограничение L1 (ромб) / L2 (круг).</span></span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       Численно найдите минимум Q на границе каждого множества (перебором по границе)</span></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       и отметьте его. Обратите внимание, где оказывается точка для ромба.</span></span></code></pre></div>\n</div>\n<div id="cell032" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему точка касания с ромбом почти всегда\nпопадает в вершину, а с кругом — никогда? Как это связано с\nнедифференцируемостью\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo></mrow><annotation encoding="application/x-tex">|\\theta_j|</annotation></semantics></math>\nв нуле?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell033" class="cell markdown">\n<hr />\n<h1 id="часть-7-байесовский-взгляд-map">Часть 7. Байесовский взгляд:\nMAP</h1>\n<p>Утверждение 2.11: при гауссовском шуме\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi><mo>∼</mo><mi>𝒩</mi><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><msup><mi>σ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\varepsilon\\sim\\mathcal N(0,\\sigma^2)</annotation></semantics></math>\nи гауссовском априорном распределении\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>θ</mi><mi>j</mi></msub><mo>∼</mo><mi>𝒩</mi><mo stretchy="false" form="prefix">(</mo><mn>0</mn><mo>,</mo><msup><mi>τ</mi><mn>2</mn></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta_j \\sim \\mathcal N(0, \\tau^2)</annotation></semantics></math></p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>θ</mi><mrow><mi mathvariant="normal">M</mi><mi mathvariant="normal">A</mi><mi mathvariant="normal">P</mi></mrow></msub><mo>=</mo><msubsup><mi>θ</mi><mi>λ</mi><mo>*</mo></msubsup><mo>,</mo><mspace width="2.0em"></mspace><mi>λ</mi><mo>=</mo><msup><mi>σ</mi><mn>2</mn></msup><mi>/</mi><msup><mi>τ</mi><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\theta_{\\mathrm{MAP}} = \\theta^*_\\lambda, \\qquad \\lambda = \\sigma^2/\\tau^2 .\n</annotation></semantics></math></p>\n<p>Аналогично, лапласовское априорное распределение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>∝</mo><msup><mi>e</mi><mrow><mi>−</mi><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo><mi>/</mi><mi>b</mi></mrow></msup></mrow><annotation encoding="application/x-tex">p(\\theta_j) \\propto e^{-|\\theta_j|/b}</annotation></semantics></math>\nдаёт LASSO с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>=</mo><mn>2</mn><msup><mi>σ</mi><mn>2</mn></msup><mi>/</mi><mi>b</mi></mrow><annotation encoding="application/x-tex">\\lambda = 2\\sigma^2/b</annotation></semantics></math>.</p>\n<p>Проверьте обе связи: минимизируйте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">-\\ln L(\\theta) - \\ln p(\\theta)</annotation></semantics></math>\nчисленно и сравните с формулами.</p>\n</div>\n<div id="cell034" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>sigma, tau, b_lap <span class="op">=</span> <span class="fl">0.3</span>, <span class="fl">0.5</span>, <span class="fl">0.4</span></span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) напишите -ln L(theta) - ln p(theta) для гауссовского и лапласовского</span></span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a><span class="co">#          априорных распределений (свободный член theta[0] не штрафуется);</span></span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) минимизируйте обе функции численно (для лапласовской подойдёт</span></span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a><span class="co">#          method=&quot;Powell&quot; -- функция негладкая);</span></span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) сравните с ridge_fit(lambda = sigma^2/tau^2) и lasso_cd(lambda = 2 sigma^2/b);</span></span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) нарисуйте обе априорные плотности на одном графике.</span></span></code></pre></div>\n</div>\n<div id="cell035" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли MAP-оценки с формулами? Посмотрите\nна графики априорных плотностей: какая из них сильнее «настаивает» на\nтом, что вес равен нулю, и как это объясняет разреженность LASSO?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell036" class="cell markdown">\n<hr />\n<h1 id="часть-8-своя-выборка">Часть 8. Своя выборка</h1>\n<p>Примените регуляризацию из вашего варианта\n(<code>variant[&quot;own_regularizer&quot;]</code>) к индивидуальной выборке.\nПараметр\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>\nподбирайте по <strong>отложенной части обучающей выборки</strong> —\nконтрольную выборку трогать нельзя, она нужна для финальной оценки.\nПолноценный скользящий контроль появится в работе 5.</p>\n<blockquote>\n<p><strong>Про сетку\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>.</strong>\nФиксированная сетка вроде <code>np.logspace(-3, 4)</code> — частая\nошибка: осмысленный масштаб\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>\nзависит от масштаба\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>X</mi><annotation encoding="application/x-tex">X</annotation></semantics></math>.\nДля нашей нормировки штраф начинает действовать, когда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>\nсравним с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">⟨</mo><msub><mi>x</mi><mi>j</mi></msub><mo>,</mo><mi>y</mi><mo>−</mo><mover><mi>y</mi><mo accent="true">¯</mo></mover><mo stretchy="false" form="postfix">⟩</mo></mrow><annotation encoding="application/x-tex">\\langle x_j, y - \\overline y\\rangle</annotation></semantics></math>.\nИз условия обнуления координаты\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mo stretchy="false" form="prefix">⟨</mo><msub><mi>x</mi><mi>j</mi></msub><mo>,</mo><mi>r</mi><mo stretchy="false" form="postfix">⟩</mo><mo stretchy="false" form="prefix">|</mo><mo>≤</mo><mi>λ</mi><mi>/</mi><mn>2</mn></mrow><annotation encoding="application/x-tex">|\\langle x_j, r\\rangle| \\le \\lambda/2</annotation></semantics></math>\nполучается <strong>наименьшее\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>,\nобнуляющее все веса</strong>:\n<math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>λ</mi><mi>max</mi></msub><mo>=</mo><mn>2</mn><munder><mi>max</mi><mi>j</mi></munder><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">|</mo><mo stretchy="false" form="prefix">⟨</mo><msub><mi>x</mi><mi>j</mi></msub><mo>,</mo><mspace width="0.167em"></mspace><mi>y</mi><mo>−</mo><mover><mi>y</mi><mo accent="true">¯</mo></mover><mo stretchy="false" form="postfix">⟩</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">|</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\\lambda_{\\max} = 2\\max_j \\bigl|\\langle x_j,\\, y - \\overline y\\rangle\\bigr| .</annotation></semantics></math>\nРазумная сетка — от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>10</mn><mrow><mi>−</mi><mn>4</mn></mrow></msup><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">10^{-4}\\lambda_{\\max}</annotation></semantics></math>\nдо\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>λ</mi><mi>max</mi></msub><annotation encoding="application/x-tex">\\lambda_{\\max}</annotation></semantics></math>:\nслева МНК, справа константа, и весь интересный диапазон гарантированно\nвнутри.</p>\n</blockquote>\n</div>\n<div id="cell037" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a>Xtr_full, Xte <span class="op">=</span> data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>]</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a>ytr_full, yte <span class="op">=</span> data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]</span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) отделите от обучающей выборки валидационную часть (25%);</span></span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) постройте сетку от 1e-4 * lambda_max до lambda_max, где</span></span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          lambda_max = 2 * max_j |&lt;x_j, y - mean(y)&gt;| (см. врезку выше),</span></span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          обучите модель из своего варианта и выберите lambda по ошибке</span></span>\n<span id="cb15-11"><a href="#cb15-11" aria-hidden="true" tabindex="-1"></a><span class="co">#          на валидационной части;</span></span>\n<span id="cb15-12"><a href="#cb15-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) переобучите модель с lambda* на ВСЕЙ обучающей выборке;</span></span>\n<span id="cb15-13"><a href="#cb15-13" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) сравните на контроле: константа / МНК / ваша регуляризованная модель;</span></span>\n<span id="cb15-14"><a href="#cb15-14" aria-hidden="true" tabindex="-1"></a><span class="co">#       5) выведите 8 признаков с наибольшими |коэффициентами| и число ненулевых.</span></span></code></pre></div>\n</div>\n<div id="cell038" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Улучшила ли регуляризация качество на\nконтроле по сравнению с чистым МНК? Какое\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>λ</mi><mo>*</mo></msup><annotation encoding="application/x-tex">\\lambda^*</annotation></semantics></math>\nвыбрано — ближе к левому или к правому концу сетки?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell039" class="cell markdown">\n<h3 id="задание-82-ситуация-в-которой-регуляризация-решает">Задание 8.2.\nСитуация, в которой регуляризация решает</h3>\n<p>Расширьте признаковое пространство всеми попарными произведениями\nпризнаков (<code>PolynomialFeatures(degree=2)</code>) и <strong>урежьте\nобучающую выборку</strong> до 120 объектов. Теперь\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo>&gt;</mo><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">p &gt; \\ell</annotation></semantics></math>:\nматрица\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>X</mi><mi>𝖳</mi></msup><mi>X</mi></mrow><annotation encoding="application/x-tex">X^{\\mathsf T}X</annotation></semantics></math>\nзаведомо вырождена, МНК не определён однозначно, и без регуляризации\nзадача не решается.</p>\n<p>Сравните на контроле: МНК (<code>lstsq</code>, решение минимальной\nнормы), Ridge и LASSO с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>λ</mi><annotation encoding="application/x-tex">\\lambda</annotation></semantics></math>,\nподобранным по отложенной части. Здесь допустимо использовать реализации\n<code>sklearn</code> — свои вы уже проверили в частях 5 и 6.</p>\n</div>\n<div id="cell040" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb16"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb16-1"><a href="#cb16-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> Lasso, Ridge</span>\n<span id="cb16-2"><a href="#cb16-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> PolynomialFeatures, StandardScaler</span>\n<span id="cb16-3"><a href="#cb16-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb16-4"><a href="#cb16-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) расширьте признаки PolynomialFeatures(degree=2, include_bias=False)</span></span>\n<span id="cb16-5"><a href="#cb16-5" aria-hidden="true" tabindex="-1"></a><span class="co">#          и отмасштабируйте их StandardScaler; обучающую выборку урежьте до 120 объектов;</span></span>\n<span id="cb16-6"><a href="#cb16-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) убедитесь, что p &gt; l и ранг X^T X меньше числа признаков;</span></span>\n<span id="cb16-7"><a href="#cb16-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) подберите alpha для Ridge и Lasso по отложенной части (30 % обучения),</span></span>\n<span id="cb16-8"><a href="#cb16-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          сетка от 1e-4 * alpha_max до alpha_max, где</span></span>\n<span id="cb16-9"><a href="#cb16-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          alpha_max = max_j |&lt;x_j, y - mean(y)&gt;| / l  (нормировка sklearn);</span></span>\n<span id="cb16-10"><a href="#cb16-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) сравните на контроле: МНК (lstsq), Ridge, LASSO, константу;</span></span>\n<span id="cb16-11"><a href="#cb16-11" aria-hidden="true" tabindex="-1"></a><span class="co">#       5) постройте график MSE(alpha) для обоих методов.</span></span></code></pre></div>\n</div>\n<div id="cell041" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Во сколько раз регуляризация выиграла у МНК\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo>&gt;</mo><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">p &gt; \\ell</annotation></semantics></math>?\nСколько признаков оставил LASSO из общего числа? Сравните с заданием 8.1\nи сформулируйте правило, когда регуляризация нужна.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell042" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Утверждение 2.2 требует\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>η</mi><mo>&lt;</mo><mn>1</mn><mi>/</mi><msub><mi>λ</mi><mi>max</mi></msub></mrow><annotation encoding="application/x-tex">\\eta &lt; 1/\\lambda_{\\max}</annotation></semantics></math>.\nКак изменится граница, если минимизировать усреднённый функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mn>1</mn><mi>ℓ</mi></mfrac><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\frac1\\ell\\|X\\theta-y\\|^2</annotation></semantics></math>?\nПроверьте ответ по своему коду.</li>\n<li>Почему SGD с постоянным шагом не сходится в точку, а мини-пакетный с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">|</mo><mi>B</mi><mo stretchy="false" form="prefix">|</mo><mo>=</mo><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">|B| = \\ell</annotation></semantics></math>\n— сходится? Что даёт компромисс по размеру пакета?</li>\n<li>Два признака имеют корреляцию 0.999. Что произойдёт с оценками их\nкоэффициентов и с их суммой\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>θ</mi><mn>1</mn></msub><mo>+</mo><msub><mi>θ</mi><mn>2</mn></msub></mrow><annotation encoding="application/x-tex">\\theta_1 + \\theta_2</annotation></semantics></math>?\nКакая из двух величин оценивается устойчиво?</li>\n<li>Почему в определении 2.7 свободный член не штрафуется? Что произошло\nбы с решением, если прибавить ко всем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>y</mi><mi>i</mi></msub><annotation encoding="application/x-tex">y_i</annotation></semantics></math>\nконстанту 1000, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>θ</mi><mn>0</mn></msub><annotation encoding="application/x-tex">\\theta_0</annotation></semantics></math>\nпри этом штрафовать?</li>\n<li>Ridge и LASSO дают одинаковое качество на вашей задаче. Какой из них\nвы выберете и почему? Назовите по одному аргументу за каждый.</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong>Ridge через расширенную выборку.</strong> Докажите, что\nрешение гребневой регрессии совпадает с обычным МНК для выборки,\nдополненной\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>n</mi><annotation encoding="application/x-tex">n</annotation></semantics></math>\n«искусственными» объектами: к матрице\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>X</mi><annotation encoding="application/x-tex">X</annotation></semantics></math>\nснизу приписывается\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msqrt><mi>λ</mi></msqrt><mspace width="0.167em"></mspace><mover><mi>D</mi><mo accent="true">̃</mo></mover></mrow><annotation encoding="application/x-tex">\\sqrt{\\lambda}\\,\\tilde D</annotation></semantics></math>\n(где\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mover><mi>D</mi><mo accent="true">̃</mo></mover><annotation encoding="application/x-tex">\\tilde D</annotation></semantics></math>\n— единичная матрица без строки свободного члена), а к\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>y</mi><annotation encoding="application/x-tex">y</annotation></semantics></math>\n— нули. Проверьте численно, что <code>fit_lstsq</code> на расширенной\nматрице даёт то же, что <code>ridge_fit</code>. Объясните, почему такой\nприём делает задачу невырожденной при любом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>λ</mi><mo>&gt;</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\lambda&gt;0</annotation></semantics></math>.</p></li>\n<li><p><strong>Elastic Net покоординатным спуском.</strong> Обобщите\n<code>lasso_cd</code> на функционал\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>+</mo><msub><mi>λ</mi><mn>1</mn></msub><mo>∑</mo><mo stretchy="false" form="prefix">|</mo><msub><mi>θ</mi><mi>j</mi></msub><mo stretchy="false" form="prefix">|</mo><mi>+</mi><msub><mi>λ</mi><mn>2</mn></msub><mo>∑</mo><msubsup><mi>θ</mi><mi>j</mi><mn>2</mn></msubsup></mrow><annotation encoding="application/x-tex">\\|X\\theta-y\\|^2 + \\lambda_1\\sum|\\theta_j| + \\lambda_2\\sum\\theta_j^2</annotation></semantics></math>:\nвыведите формулу покоординатного обновления (она отличается от LASSO\nтолько знаменателем) и сверьтесь со\n<code>sklearn.linear_model.ElasticNet</code>. Постройте пути для трёх\nзначений <code>l1_ratio</code> на двух почти дублирующих друг друга\nпризнаках и объясните «эффект группировки»: почему LASSO выбирает из\nпары один признак произвольно, а Elastic Net делит вес между\nобоими.</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);